type Fig = Partial<FigureSpec> & Pick<FigureSpec, "character" | "pose" | "expression">;
const fig = (f: Fig): FigureSpec => ({ facing: "right", slot: "center", ...f });

const say = (speaker: string, text: string, fidelity: TextSpec["fidelity"], source?: SourceRef): TextSpec =>
  source ? { kind: "speech", speaker, text, fidelity, source } : { kind: "speech", speaker, text, fidelity };

function panel(p: Omit<PanelSpec, "props" | "fx" | "figures" | "text"> & Partial<Pick<PanelSpec, "props" | "fx" | "figures" | "text">>): PanelSpec {
  return { figures: [], props: [], fx: [], text: [], ...p };
}

